var num = 720;
var x = new Float32Array(num);
var y = new Float32Array(num);
var vx = new Float32Array(num);
var vy = new Float32Array(num);
var maxDistSq = 20 ** 2;
var minDistSq = 16 ** 2;

setup = () => {
  createCanvas(m=640, 640);
  angleMode(DEGREES);
  for (let i = num; i--; ) {
    const a = i / 2;
    vx[i] = cos(a);
    vy[i] = sin(a);
    x[i] = width / 2 + (vx[i] * width) / 2;
    y[i] = height / 2 + (vy[i] * height) / 2;
  }
};

draw = () => {
  background("white");
  stroke("black");
  for (let i = num; i--; ) {
    for (let j = i; j--; ) {
      d = (x[i] - x[j]) ** 2 + (y[i] - y[j]) ** 2;
      if(minDistSq < d && d < maxDistSq)
        line(x[i], y[i], x[j], y[j]);
    }
  }
  for (let i = num; i--; ) {
    x[i] += vx[i];
    y[i] += vy[i];
    if (x[i] < 0 || x[i] > width) vx[i] *= -1;
    if (y[i] < 0 || y[i] > height) vy[i] *= -1;
  }
};
